/** TermsManagementMapper.delete */
DELETE FROM TERMS
WHERE
	TERMS_ID = #{termsId}

mapper.update:
		/** TermsManagementMapper.updateUserTermsSearch */
		UPDATE TERMS_SEARCH
		SET
			TITLE = #{title},
            CONTENTS = #{contents},
            CONTENT_TYPE = #{contentType},
            ORDER_NO = #{orderNo},
			REQUIRE_YN = #{requireYn}
		WHERE
			TERMS_ID = #{termsId}
